    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<number>#'", "1.5s"));
    TEST_ASSERT_EQUAL_STRING("KEEP", cv("'<time>#'", "round(-75.0s, 34s  /  -4.14492  )"));
    TEST_ASSERT_EQUAL_STRING("203%", cv("'<percentage>'", "max( +215%  + \t -12%, -84%\t*  116.91 )"));
